// The previous runtime's dispatcher and handlers answered the requests of testdata/checkpoints-golden.json and
// testdata/changes-golden.json (generated by testdata/timeline/gen.mjs) on the same files; the Go routes must answer
// alike: status, the headers a caller acts on, body.

type goldenTab struct {
	TabID   string `json:"tabId"`
	Session string `json:"session"`
	State   string `json:"state"`
	Flips   bool   `json:"flips"`
}

type goldenAnswer struct {
	Status        int               `json:"status"`
	AnswerHeaders map[string]string `json:"answerHeaders"`
	Answer        *string           `json:"answer"`
	AnswerSha1    string            `json:"answerSha1"`
}

type goldenStep struct {
	Now      *int64                     `json:"now"`
	Tabs     []goldenTab                `json:"tabs"`
	Cwds     map[string]string          `json:"cwds"`
	Actions  []scripttest.Action        `json:"actions"`
	Snapshot *struct{ Tab, Cwd string } `json:"snapshot"`
	Request  *struct {
		Method  string            `json:"method"`
		URL     string            `json:"url"`
		Headers map[string]string `json:"headers"`
		Body    json.RawMessage   `json:"body"`
	} `json:"request"`
	Answer *goldenAnswer `json:"answer"`
}

// goldenRouter is a gate with the timeline and fsread slices on and the test's auth: the cookie session-token=good is
// a page session, x-cli-token the runtime's token.
func goldenRouter(t *testing.T, w *scripttest.World, token string, add func(f *gate.Gate, d deps)) *gate.Gate {
	data := filepath.Join(w.Root, "data")
	_ = os.WriteFile(filepath.Join(data, "state-mode.json"), []byte(`{"goSlices":["timeline","fsread"]}`), 0o600)
	f, err := gate.New(gate.Config{Upstream: "127.0.0.1:1", DataDir: data})
	if err != nil {
		t.Fatal(err)
	}
	sessionOK := func(r *http.Request) bool { return strings.Contains(r.Header.Get("Cookie"), "session-token=good") }
	d := deps{Home: filepath.Join(w.Root, "home"), DataDir: data, SessionOK: sessionOK,
		APIRefusal: func(r *http.Request) (int, any, http.Header, bool) {
			if sessionOK(r) || r.Header.Get("x-cli-token") == token {
				return 0, nil, nil, false
			}
			return http.StatusUnauthorized, map[string]string{"error": "Unauthorized"}, http.Header{"Content-Type": {"application/json"}}, true
		}}
	add(f, d)
	return f
}

func replayGolden(t *testing.T, file string, roots []string, setup func(w *scripttest.World, step goldenStep), add func(f *gate.Gate, d deps)) {
	raw, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	var golden struct {
		Token string       `json:"token"`
		Steps []goldenStep `json:"steps"`
	}
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatal(err)
	}
	w := scripttest.New(t, roots)
	f := goldenRouter(t, w, golden.Token, add)
	lastETag := ""
	for i, step := range golden.Steps {
		w.Apply(step.Actions)
		setup(w, step)
		if step.Request == nil {
			continue
		}
		rq := step.Request
		var body string
		if len(rq.Body) > 0 {
			var s string
			var pad struct{ Padding int }
			if json.Unmarshal(rq.Body, &s) == nil {
				body = strings.ReplaceAll(s, "$ROOT", w.Root)
			} else if json.Unmarshal(rq.Body, &pad) == nil {
				body = `{"x":"` + strings.Repeat("a", pad.Padding) + `"}`
			}
		}
		r := httptest.NewRequest(rq.Method, strings.ReplaceAll(rq.URL, "$ROOT", w.Root), strings.NewReader(body))
		for k, v := range rq.Headers {
			switch v {
			case "TOKEN":
				v = golden.Token
			case "ETAG":
				v = lastETag
			}
			r.Header.Set(k, v)
		}
		rec := httptest.NewRecorder()
		f.ServeHTTP(rec, r)
		res := rec.Result()
		got := w.Scrub(rec.Body.String())
		want := step.Answer
		name := rq.Method + " " + rq.URL
		if res.StatusCode != want.Status {
			t.Errorf("%d %s: status %d, want %d (%s)", i, name, res.StatusCode, want.Status, got)
			continue
		}
		if want.Answer != nil && got != *want.Answer {
			t.Errorf("%d %s:\n got %s\nwant %s", i, name, got, *want.Answer)
		}
		if want.AnswerSha1 != "" {
			if sum := sha1.Sum([]byte(got)); hex.EncodeToString(sum[:]) != want.AnswerSha1 {
				t.Errorf("%d %s: long answer differs (%d bytes): %.300s", i, name, len(got), got)
			}
		}
		for _, k := range []string{"content-type", "etag", "allow", "cache-control"} {
			g, wv := res.Header.Get(k), want.AnswerHeaders[k]
			if k == "etag" && wv != "" && (want.Answer == nil || strings.Contains(*want.Answer, "$ROOT")) {
				// The body names the temporary folder: the tag must be that of the bytes sent.
				if g != nodejson.ETag(rec.Body.Bytes()) {
					t.Errorf("%d %s: etag %q is not the body's", i, name, g)
				}
				continue
			}
			if g != wv {
				t.Errorf("%d %s: %s %q, want %q", i, name, k, g, wv)
			}
		}
		if e := res.Header.Get("ETag"); e != "" {
			lastETag = e
		}
	}
}

func TestGoldenCheckpointsRoute(t *testing.T) {
	var now int64
	var tabs map[string]goldenTab
	seen := map[string]int{}
	cwds := map[string]string{}
	var store *checkpoints.Store
	replayGolden(t, "testdata/checkpoints-golden.json", []string{"api-h"}, func(w *scripttest.World, step goldenStep) {
		if store == nil {
			store = &checkpoints.Store{Dir: filepath.Join(w.Root, "data", "checkpoints"), Home: filepath.Join(w.Root, "home"), Namespace: "acme", TmpTag: "hs",
				Now: func() int64 { return now }}
		}
		if step.Now != nil {
			now = *step.Now
		}
		if step.Tabs != nil {
			tabs = map[string]goldenTab{}
			for _, tb := range step.Tabs {
				tabs[tb.TabID] = tb
			}
			for s, c := range step.Cwds {
				cwds[s] = filepath.Join(w.Root, c)
			}
		}
		if step.Snapshot != nil {
			store.SnapshotTurnEnd(step.Snapshot.Tab, filepath.Join(w.Root, step.Snapshot.Cwd))
		}
	}, func(f *gate.Gate, d deps) {
		api := &checkpoints.API{
			Store: &checkpoints.Store{Dir: filepath.Join(d.DataDir, "checkpoints"), Home: d.Home, Namespace: "acme", TmpTag: "hs", Now: func() int64 { return now }},
			Tab: func(id string) (string, string, bool) {
				tb, ok := tabs[id]
				if !ok {
					return "", "", false
				}
				seen[id]++
				if tb.Flips && seen[id] > 1 {
					return tb.Session, "busy", true
				}
				return tb.Session, tb.State, true
			},
			Cwd: func(s string) string { return cwds[s] },
		}
		f.Add(f.AsRoutes(checkpointsRoute(d, func() bool { return true }, api))...)
	})
}

func TestCheckpointsRouteNeedsTheCore(t *testing.T) {
	route := checkpointsRoute(deps{}, func() bool { return false }, &checkpoints.API{})
	for _, p := range []string{"/api/platform/checkpoints", "/agents/api/platform/checkpoints"} {
		if route.Match(httptest.NewRequest("GET", p+"?tabId=x", nil)) {
			t.Errorf("%s matched with the core off", p)
		}
	}
	on := checkpointsRoute(deps{}, func() bool { return true }, &checkpoints.API{})
	if !on.Match(httptest.NewRequest("POST", "/agents/api/platform/checkpoints", nil)) || on.Match(httptest.NewRequest("GET", "/api/platform/checkpoints/x", nil)) {
		t.Error("path forms")
	}
}
